-- What the preset does: each everyday permission the members role does not
-- hold yet, from no to yes. The set is the member-rights step's
-- (grant_member_essentials.dart).
create or replace function public.setup_member_rights_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_changes jsonb;
begin
  if coalesce(p_args->>'preset', '') <> 'members_can_book' then
    raise exception 'preset is members_can_book' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('field', e.perm, 'from', false, 'to', true) order by e.ord), '[]'::jsonb)
    into v_changes
    from unnest(array['makeReservations', 'viewCalendar', 'useMessages', 'viewMyMoney']) with ordinality e(perm, ord)
   where not public.role_holds(p_workspace_id, 'member', e.perm);
  if v_changes = '[]'::jsonb then
    raise exception 'the members role already holds these permissions' using errcode = '22023';
  end if;
  return jsonb_build_object('changes', v_changes, 'revision', md5(v_changes::text));
end;
$fn$;
revoke execute on function public.setup_member_rights_plan(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_set_member_permissions_preset(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  perform public.mcp_setup_target_guard(p_workspace_id, p_args, array['workspace_id', 'request_id', 'preset']);
  v := public.setup_member_rights_plan(p_workspace_id, p_args);
  return jsonb_build_object('kind', 'member_rights', 'changes', v->'changes', 'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_set_member_permissions_preset(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the list. Each permission goes
-- through request_matrix_permission, the step's own command, which asks
-- manageRoles for the person again; this definer asks it first. A request
-- that waits for validators is pending, never approved here.
create or replace function public.mcp_op_set_member_permissions_preset(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'request_id', 'preset']);
  v jsonb;
  ch jsonb;
  v_answer jsonb;
  v_pending boolean := false;
begin
  if v_refusal is not null then return v_refusal; end if;
  if not public.has_permission(c.workspace_id, 'manageRoles') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  v := public.setup_member_rights_plan(c.workspace_id, p_args);
  for ch in select e from jsonb_array_elements(v->'changes') e loop
    v_answer := public.request_matrix_permission(c.workspace_id, 'member', ch->>'field', true);
    if coalesce((v_answer->>'pending')::boolean, false) then v_pending := true; end if;
  end loop;
  return public.mcp_outcome(case when v_pending then 'pending_validation' else 'completed' end,
                            jsonb_build_object('changes', v->'changes'));
end;
$fn$;
revoke execute on function public.mcp_op_set_member_permissions_preset(public.mcp_call_context, jsonb) from public, anon, authenticated;

notify pgrst, 'reload schema';

select public.set_deskilo_schema_version(625);
